public static void tremor(LivingEntity livingEntity, int distance, double topY, float side, float damage, float airborne) {
        int hitY = Mth.floor(livingEntity.getBoundingBox().minY - 0.5D);
        double minY = livingEntity.getY() - 2.0D;
        double maxY = livingEntity.getY() + topY;
        float angle = (float) ((Math.PI / 180.0F) * livingEntity.yHeadRot);
        float f = Mth.cos(livingEntity.yHeadRot * ((float) Math.PI / 180F));
        float f1 = Mth.sin(livingEntity.yHeadRot * ((float) Math.PI / 180F));
        double extraX = distance * Mth.sin((float) (Math.PI + angle));
        double extraZ = distance * Mth.cos(angle);
        double px = livingEntity.getX() + extraX + f * side;
        double pz = livingEntity.getZ() + extraZ + f1 * side;
        int hitX = Mth.floor(px);
        int hitZ = Mth.floor(pz);
        BlockPos blockPos = new BlockPos(hitX, hitY, hitZ);
        BlockPos abovePos = new BlockPos(blockPos).above();
        BlockState blockState = livingEntity.level.getBlockState(blockPos);
        BlockState blockAbove = livingEntity.level.getBlockState(abovePos);

        if (blockState != Blocks.AIR.defaultBlockState() && !blockState.hasBlockEntity() && !blockAbove.blocksMotion()) {
            ModFallingBlock fallingBlock = new ModFallingBlock(livingEntity.level, Vec3.atCenterOf(blockPos.above()), blockState, (float) (0.2D + livingEntity.getRandom().nextGaussian() * 0.15D));
            livingEntity.level.addFreshEntity(fallingBlock);
        }
        AABB selection = new AABB(px - 0.5D, minY, pz - 0.5D, px + 0.5D, maxY, pz + 0.5D);
        List<LivingEntity> entities = livingEntity.level.getEntitiesOfClass(LivingEntity.class, selection);
        for (LivingEntity target : entities) {
            if (!MobUtil.areAllies(target, livingEntity) && target != livingEntity) {
                boolean flag = target.hurt(livingEntity.damageSources().mobAttack(livingEntity), damage);
                if (flag) {
                    MobUtil.push(target, 0.0D, (double) (airborne * (float) distance) + livingEntity.getRandom().nextDouble() * 0.15D, 0.0D);
                }
            }
        }
        if (distance % 4 == 0) {
            livingEntity.level.playSound(null, blockPos.above(), ModSounds.WALL_ERUPT.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
            livingEntity.level.playSound(null, blockPos.above(), ModSounds.DIRT_DEBRIS.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
            livingEntity.level.playSound(null, blockPos.above(), SoundEvents.GENERIC_EXPLODE, SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
        }
    }

@Override
    public void useSpell(ServerLevel worldIn, LivingEntity caster, ItemStack staff, int castTime, SpellStat spellStat) {
        int range = spellStat.getRange();
        int radius = (int) spellStat.getRadius();
        float damage = SpellConfig.QuakingDamage.get().floatValue() * WandUtil.damageMultiply();
        if (WandUtil.enchantedFocus(caster)) {
            range += WandUtil.getRangeLevel(caster);
            radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster);
            damage += WandUtil.getPotencyLevel(caster);
        }
        damage += spellStat.getPotency();
        if (rightStaff(staff)) {
            radius += 1;
        }
        if (castTime > this.defaultCastDuration()) {
            if (!this.isShifting(caster)) {
                for (int i = 0; i <= range; ++i) {
                    if (castTime == i + this.defaultCastDuration()) {
                        if (rightStaff(staff)) {
                            int d = (i + 2) - 2;
                            int d2 = (i + 2) - 3;
                            float ds = (float) (d + d2) / 2;
                            arcTremor(caster, 0.35F, d, 5, 1.05F, -2.0F, 0, 80, damage);
                            arcTremor(caster, 0.35F, d2, 5, 1.05F, -2.0F, 0, 80, damage);
                            tremorSound(caster, ds, 0);
                        } else {
                            tremor(caster, i, 3, 0.0F, damage, 0.1F);
                            tremor(caster, i, 3, 1.5F, damage, 0.1F);
                            tremor(caster, i, 3, -1.5F, damage, 0.1F);
                        }
                    }
                }
            } else {
                for (int i = 0; i <= radius; ++i) {
                    if (castTime == i + this.defaultCastDuration()) {
                        surroundTremor(caster, i, 3, 0.0F, rightStaff(staff), damage, 0.1F);
                    }
                }
            }
        }
    }

@Override
    public void stopSpell(ServerLevel worldIn, LivingEntity caster, ItemStack staff, ItemStack focus, int castTime, SpellStat spellStat) {
        if (castTime > this.defaultCastDuration()){
            if (caster instanceof Player player && !focus.isEmpty()) {
                SEHelper.addSpellCooldown(player, this, this.spellCooldown(caster));
                SEHelper.sendSEUpdatePacket(player);
            }
        }
    }

public void arcTremor(LivingEntity caster, float spreadarc, int distance, int height, float mxy, float vec, float math, int shieldbreakticks, float damage) {
        double perpFacing = caster.getYRot() * (Math.PI / 180);
        double facingAngle = perpFacing + Math.PI / 2;
        int hitY = Mth.floor(caster.getBoundingBox().minY - 0.5);
        double spread = Math.PI * spreadarc;
        int arcLen = Mth.ceil(distance * spread);
        float f = Mth.cos(caster.getYRot() * ((float)Math.PI / 180F)) ;
        float f1 = Mth.sin(caster.getYRot() * ((float)Math.PI / 180F)) ;
        for (int i = 0; i < arcLen; i++) {
            double theta = (i / (arcLen - 1.0) - 0.5) * spread + facingAngle;
            double vx = Math.cos(theta);
            double vz = Math.sin(theta);
            double px = caster.getX() + vx * distance + vec * Math.cos((caster.getYRot() + 90) * Math.PI / 180) + f * math;
            double pz = caster.getZ() + vz * distance + vec * Math.sin((caster.getYRot() + 90) * Math.PI / 180) + f1 * math;
            int hitX = Mth.floor(px);
            int hitZ = Mth.floor(pz);
            BlockPos pos = new BlockPos(hitX, hitY + height, hitZ);
            BlockState block = caster.level.getBlockState(pos);

            int maxDepth = 30;
            for (int depthCount = 0; depthCount < maxDepth; depthCount++) {
                if (block.getRenderShape() == RenderShape.MODEL) {
                    break;
                }
                pos = pos.below();
                block = caster.level.getBlockState(pos);
            }

            if (block.getRenderShape() != RenderShape.MODEL) {
                block = Blocks.AIR.defaultBlockState();
            }
            if (!caster.level.isClientSide) {
                spawnBlocks(caster, hitX, hitY + height, hitZ, (int) (caster.getY() - height), block, px, pz, mxy, distance, shieldbreakticks, damage);
            }
        }
    }

private void spawnBlocks(LivingEntity caster, int hitX, int hitY, int hitZ, int lowestYCheck, BlockState blockState, double px, double pz, float mxy, float distance, int shieldbreakticks, float damage) {
        BlockPos blockpos = new BlockPos(hitX, hitY, hitZ);
        double d0 = 0.0D;

        do {
            BlockPos blockpos1 = blockpos.below();
            BlockState blockstate = caster.level.getBlockState(blockpos1);
            if (blockstate.isFaceSturdy(caster.level, blockpos1, Direction.UP)) {
                if (!caster.level.isEmptyBlock(blockpos)) {
                    BlockState blockstate1 = caster.level.getBlockState(blockpos);
                    VoxelShape voxelshape = blockstate1.getCollisionShape(caster.level, blockpos);
                    if (!voxelshape.isEmpty()) {
                        d0 = voxelshape.max(Direction.Axis.Y);
                    }
                }

                break;
            }

            blockpos = blockpos.below();
        } while(blockpos.getY() >= Mth.floor(lowestYCheck) - 1);

        ModFallingBlock fallingBlock = new ModFallingBlock(caster.level, Vec3.atCenterOf(blockpos.above()), blockState, (float) (0.2D + caster.getRandom().nextGaussian() * 0.04D));
        caster.level.addFreshEntity(fallingBlock);

        AABB selection = new AABB(px - 0.5, (double)blockpos.getY() + d0 -1, pz - 0.5, px + 0.5, (double)blockpos.getY() + d0 + mxy, pz + 0.5);
        List<LivingEntity> hitbox = caster.level.getEntitiesOfClass(LivingEntity.class, selection);

        for (LivingEntity entity : hitbox) {
            if (!MobUtil.areAllies(caster, entity)) {
                boolean flag = entity.hurt(caster.damageSources().mobAttack(entity), damage);
                if (entity.isDamageSourceBlocked(caster.damageSources().mobAttack(entity)) && shieldbreakticks > 0) {
                    MobUtil.disableShield(entity);
                }
                if (flag) {
                    MobUtil.push(entity, 0.0D, (double) (0.1F * distance) + entity.getRandom().nextDouble() * 0.15D, 0.0D);
                }
            }
        }

    }

private void tremorSound(LivingEntity livingEntity, float distance, float math) {
        double theta = (livingEntity.getYRot()) * (Math.PI / 180);
        theta += Math.PI / 2;
        double vecX = Math.cos(theta);
        double vecZ = Math.sin(theta);
        float f = Mth.cos(livingEntity.getYRot() * ((float)Math.PI / 180F)) ;
        float f1 = Mth.sin(livingEntity.getYRot() * ((float)Math.PI / 180F)) ;
        livingEntity.level.playSound(null, livingEntity.getX() + distance * vecX + f * math, livingEntity.getY(), livingEntity.getZ() + distance * vecZ + f1 * math, ModSounds.WALL_ERUPT.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
        livingEntity.level.playSound(null, livingEntity.getX() + distance * vecX + f * math, livingEntity.getY(), livingEntity.getZ() + distance * vecZ + f1 * math, ModSounds.DIRT_DEBRIS.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
        livingEntity.level.playSound(null, livingEntity.getX() + distance * vecX + f * math, livingEntity.getY(), livingEntity.getZ() + distance * vecZ + f1 * math, SoundEvents.GENERIC_EXPLODE, SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
    }

public static void surroundTremor(LivingEntity livingEntity, int distance, double topY, float side, boolean grab, float damage, float airborne) {
        int hitY = Mth.floor(livingEntity.getBoundingBox().minY - 0.5D);
        double spread = Math.PI * (double)2.0F;
        int arcLen = Mth.ceil((double)distance * spread);
        double minY = livingEntity.getY() - 1.0D;
        double maxY = livingEntity.getY() + topY;

        for(int i = 0; i < arcLen; ++i) {
            double theta = ((double)i / ((double)arcLen - 1.0D) - 0.5D) * spread;
            double vx = Math.cos(theta);
            double vz = Math.sin(theta);
            double px = livingEntity.getX() + vx * (double)distance + (double)side * Math.cos((double)(livingEntity.yBodyRot + 90.0F) * Math.PI / 180.0D);
            double pz = livingEntity.getZ() + vz * (double)distance + (double)side * Math.sin((double)(livingEntity.yBodyRot + 90.0F) * Math.PI / 180.0D);
            float factor = 1.0F - (float)distance / 12.0F;
            int hitX = Mth.floor(px);
            int hitZ = Mth.floor(pz);
            BlockPos blockPos = new BlockPos(hitX, hitY, hitZ);

            BlockState blockState;
            for(blockState = livingEntity.level.getBlockState(blockPos); blockState.getRenderShape() != RenderShape.MODEL; blockState = livingEntity.level.getBlockState(blockPos)) {
                blockPos = blockPos.below();
            }
            BlockState blockAbove = livingEntity.level.getBlockState(blockPos.above());

            if (blockState != Blocks.AIR.defaultBlockState() && !blockState.hasBlockEntity() && !blockAbove.blocksMotion()) {
                ModFallingBlock fallingBlock = new ModFallingBlock(livingEntity.level, Vec3.atCenterOf(blockPos.above()), blockState, (float) (0.2D + livingEntity.getRandom().nextGaussian() * 0.15D));
                livingEntity.level.addFreshEntity(fallingBlock);
            }

            if (distance % 4 == 0) {
                livingEntity.level.playSound(null, blockPos.above(), ModSounds.WALL_ERUPT.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
                livingEntity.level.playSound(null, blockPos.above(), ModSounds.DIRT_DEBRIS.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
                livingEntity.level.playSound(null, blockPos.above(), SoundEvents.GENERIC_EXPLODE, SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
            }

            AABB selection = new AABB(px - 0.5D, minY, pz - 0.5D, px + 0.5D, maxY, pz + 0.5D);
            List<LivingEntity> entities = livingEntity.level.getEntitiesOfClass(LivingEntity.class, selection);
            for (LivingEntity target : entities) {
                if (!MobUtil.areAllies(target, livingEntity) && target != livingEntity) {
                    boolean flag = target.hurt(livingEntity.damageSources().mobAttack(livingEntity), damage);
                    if (flag) {
                        if (grab) {
                            if (target.isDamageSourceBlocked(livingEntity.damageSources().mobAttack(livingEntity))) {
                                MobUtil.disableShield(target);
                            }
                        } else {
                            MobUtil.push(target, 0.0D, (double) (airborne * (float) distance) + livingEntity.getRandom().nextDouble() * 0.15D, 0.0D);
                        }
                    }
                }
            }
        }

    }

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        int potency = spellStat.getPotency();
        int duration = spellStat.getDuration();
        int range = spellStat.getRange();
        if (WandUtil.enchantedFocus(caster)) {
            potency += WandUtil.getPotencyLevel(caster);
            duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
            range += WandUtil.getRangeLevel(caster);
        }
        float damage = this.damage + potency;
        if (!worldIn.isClientSide) {
            for (Entity target : getBreathTarget(caster, range)) {
                if (target != null) {
                    if (target.hurt(ModDamageSource.swarm(caster, caster), damage)){
                        if (rightStaff(staff)) {
                            if (target instanceof LivingEntity livingTarget) {
                                MobEffect mobEffect = MobEffects.POISON;
                                if (CuriosFinder.hasWildRobe(caster)) {
                                    mobEffect = GoetyEffects.ACID_VENOM.get();
                                }
                                livingTarget.addEffect(new MobEffectInstance(mobEffect, MathHelper.secondsToTicks(5) * duration));
                            }
                        }
                        if (!target.isAlive()){
                            InsectSwarm insectSwarm = new InsectSwarm(worldIn, caster, target.position());
                            insectSwarm.setLimitedLife(200 * duration);
                            if (potency > 0){
                                insectSwarm.addEffect(new MobEffectInstance(GoetyEffects.BUFF.get(), EffectsUtil.infiniteEffect(), potency - 1, false, false));
                            }
                            worldIn.addFreshEntity(insectSwarm);
                        }
                    }
                }
            }
        }
        this.playSound(worldIn, caster, ModSounds.INSECT_SWARM.get(), worldIn.random.nextFloat() * 0.5F, worldIn.random.nextFloat() * 0.5F);
    }

@Override
    public void tick() {
        super.tick();
        if (!this.level.isClientSide) {
            if (this.tickCount % 2 == 0) {
                if (this.level instanceof ServerLevel serverLevel) {
                    ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, ModParticleTypes.FLY.get(), this);
                }
            }
            if (this.getTarget() != null) {
                this.navigation.moveTo(this.getTarget(), 7.0D);
            } else {
                Vec3 vec3 = LandRandomPos.getPos(this, 10, 7);
                if (vec3 == null){
                    vec3 = DefaultRandomPos.getPos(this, 10, 7);
                }
                if (vec3 != null){
                    this.navigation.moveTo(vec3.x, vec3.y, vec3.z, 1.0D);
                }
            }
            if (this.level.collidesWithSuffocatingBlock(this, this.getBoundingBox().move(0.0D, -1.0D, 0.0D))) {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, 0.02D, 0.0D));
            } else {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.008D, 0.0D));
            }
            if (!this.moveControl.hasWanted()) {
                this.setDeltaMovement(this.getDeltaMovement().multiply(0.95F, 1.0F, 0.95F));
            }
            float inflate = 2.0F - this.getBbWidth() * 0.5F;
            for (LivingEntity living : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(inflate))) {
                if (living != this && !MobUtil.areAllies(this, living) && SummonTargetGoal.predicate(this).test(living)) {
                    if (living.hurt(ModDamageSource.swarm(this, this.getTrueOwner()), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE))) {
                        this.playSound(ModSounds.INSECT_SWARM_BITE.get(), 1.0F, this.getVoicePitch());
                        int speed = (int) ((this.getHealth() / this.getMaxHealth()) * 5);
                        living.invulnerableTime = Math.min(20, (20 - speed));
                        this.hurt(this.damageSources().starve(), 2.0F);
                        if (this.getTrueOwner() != null && CuriosFinder.hasWildRobe(this.getTrueOwner())){
                            living.addEffect(new MobEffectInstance(GoetyEffects.ACID_VENOM.get(), MathHelper.secondsToTicks(5)));
                        }
                    }
                }
            }
        }
    }

@Override
    public void lifeSpanDamage() {
        this.dismiss();
    }

@Override
    public void dismiss() {
        this.discard();
    }

default List<Entity> getBreathTarget(LivingEntity livingEntity, double range) {
        return MobUtil.getTargets(livingEntity.level, livingEntity, range, 3.0D);
    }

public static List<Entity> getTargets(Level level, LivingEntity pSource, double pRange, double pRadius) {
        return getTargets(level, pSource, pRange, pRadius, EntitySelector.NO_CREATIVE_OR_SPECTATOR.and(LIVING_OR_PART).and(entity -> !MobUtil.areAllies(entity, pSource)));
    }

public static List<Entity> getTargets(Level level, LivingEntity pSource, double pRange, double pRadius, Predicate<? super Entity> predicate) {
        return getTargets(level, pSource, pSource.getEyePosition(), pRange, pRadius, predicate);
    }

public static List<Entity> getTargets(Level level, LivingEntity pSource, Vec3 srcVec, double pRange, double pRadius, Predicate<? super Entity> predicate) {
        return getTargets(level, pSource, srcVec, pSource.getViewVector(1.0F), pRange, pRadius, predicate);
    }

public static List<Entity> getTargets(Level level, LivingEntity pSource, Vec3 srcVec, Vec3 lookVec, double pRange, double pRadius, Predicate<? super Entity> predicate) {
        List<Entity> list = new ArrayList<>();
        double[] lookRange = new double[] {lookVec.x() * pRange, lookVec.y() * pRange, lookVec.z() * pRange};
        Vec3 destVec = srcVec.add(lookRange[0], lookRange[1], lookRange[2]);
        List<Entity> possibleList = level.getEntities(pSource, pSource.getBoundingBox().expandTowards(lookRange[0], lookRange[1], lookRange[2]).inflate(pRadius, pRadius, pRadius),
                predicate);
        double hitDist = 0.0D;

        for (Entity hit : possibleList) {
            if (hit.isPickable() && pSource.hasLineOfSight(hit) && hit != pSource) {
                float maxSize = pSource instanceof Mob ? 2.0F : 0.8F;
                float borderSize = Math.max(maxSize, hit.getPickRadius());
                AABB collisionBB = hit.getBoundingBox().inflate(borderSize);
                Optional<Vec3> interceptPos = collisionBB.clip(srcVec, destVec);
                if (collisionBB.contains(srcVec)) {
                    if (0.0D <= hitDist) {
                        list.add(hit);
                        hitDist = 0.0D;
                    }
                } else if (interceptPos.isPresent()) {
                    double possibleDist = srcVec.distanceTo(interceptPos.get());

                    if (possibleDist < hitDist || hitDist == 0.0D) {
                        list.add(hit);
                        hitDist = possibleDist;
                    }
                }
            }
        }
        return list;
    }

public void tick(){
        super.tick();
        this.ownedTick();
    }

@Nullable
    public LivingEntity getTrueOwner() {
        if (this.hasEffect(GoetyEffects.WILD_RAGE.get())) {
            return null;
        }
        if (!this.level.isClientSide){
            UUID uuid = this.getOwnerId();
            return uuid == null ? null : EntityFinder.getLivingEntityByUuiD(this.level, uuid);
        } else {
            int id = this.getOwnerClientId();
            return id <= -1 ? null : this.level.getEntity(this.getOwnerClientId()) instanceof LivingEntity living && living != this ? living : null;
        }
    }

default void ownedTick(){
        if (this instanceof Mob mobThis) {
            if (!mobThis.level.isClientSide) {
                if (this.getTrueOwner() instanceof IOwned owned) {
                    try {
                        if (owned.getHasSummonCheck() <= 0) {
                            owned.setHasSummonCheck(2);
                        }
                    } catch (NullPointerException ignored) {
                    }
                    if (this.getTrueOwner().isRemoved() || this.getTrueOwner().isDeadOrDying() || !this.getTrueOwner().isAlive()) {
                        if (owned.getTrueOwner() != null) {
                            this.setTrueOwner(owned.getTrueOwner());
                        } else if (!this.isHostile() && !this.isNatural() && !(owned instanceof Enemy) && !owned.isHostile()) {
                            mobThis.kill();
                        }
                    }
                }
                this.ownerCheck();
                this.targetingTick();
                if (this.getTrueOwner() instanceof Mob mobOwner) {
                    if (mobOwner instanceof Apostle apostle) {
                        if (mobThis.distanceTo(apostle) > 32) {
                            this.teleportTowards(apostle);
                        }
                    }
                    if (mobOwner.getType().is(Tags.EntityTypes.BOSSES) || mobOwner.getType().is(ModTags.EntityTypes.SUMMON_KILL)) {
                        if (mobOwner.isRemoved() || mobOwner.isDeadOrDying()) {
                            mobThis.kill();
                        }
                    }
                }
                this.mobSense();
                if (this.hasLifespan()) {
                    this.setLifespan(this.getLifespan() - 1);
                    if (this.getLifespan() <= 1) {
                        this.lifeSpanDamage();
                    }
                }
                if (this.getHasSummonCheck() > 0) {
                    this.setHasSummonCheck(this.getHasSummonCheck() - 1);
                }
                if (this.getRevivingTime() > 0) {
                    this.reviveTick();
                    this.setRevivingTime(this.getRevivingTime() - 1);
                }
                if (this.getPacifyTick() > 0) {
                    this.pacify();
                    this.setPacifyTick(this.getPacifyTick() - 1);
                }
            }
        }
    }

default void setLimitedLife(int limitedLifeTicksIn) {
        this.setHasLifespan(true);
        this.setLifespan(limitedLifeTicksIn);
    }

public static void chainLightning(LivingEntity pTarget, @Nullable LivingEntity pAttacker, ColorUtil colorUtil, double range, float damage, boolean small) {
        Level level = pTarget.level;

        List<Entity> harmed = new ArrayList<>();
        Predicate<Entity> selector = entity -> entity instanceof LivingEntity livingEntity && !harmed.contains(livingEntity);
        if (pAttacker != null){
            selector = selector.and(entity -> entity instanceof LivingEntity livingEntity && livingEntity != pAttacker && MobUtil.canAttack(pAttacker, livingEntity));
        }
        Entity prevTarget = pTarget;

        int hops = level.isThundering() ? 8 : 4;

        for (int i = 0; i < hops; i++) {
            AABB aabb = new AABB(Vec3Util.subtract(prevTarget.position(), range), Vec3Util.add(prevTarget.position(), range));
            Entity finalPrevTarget = prevTarget;
            List<Entity> entities = level.getEntities(prevTarget, aabb, selector.and(entity -> MobUtil.hasLineOfSight(finalPrevTarget, entity)));
            if (!entities.isEmpty()) {
                Entity target = entities.get(level.getRandom().nextInt(entities.size()));
                DamageSource damageSource = ModDamageSource.getDamageSource(pTarget.level, ModDamageSource.SHOCK);
                if (pAttacker != null){
                    damageSource = ModDamageSource.directShock(pAttacker);
                }
                if (target.hurt(damageSource, damage)) {
                    if (prevTarget != target) {
                        Vec3 vec3 = prevTarget.getEyePosition();
                        Vec3 vec31 = target.getEyePosition();
                        if (small){
                            ModNetwork.sendToALL(new SLightningPacket(vec3, vec31, colorUtil, 5));
                        } else {
                            ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, colorUtil, 8));
                        }
                    }
                }

                harmed.add(target);
                prevTarget = target;
                damage--;
            }
        }
    }

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        int range = spellStat.getRange();
        float damage = SpellConfig.ThunderboltDamage.get().floatValue() * WandUtil.damageMultiply();
        if (WandUtil.enchantedFocus(caster)) {
            range += WandUtil.getRangeLevel(caster);
            damage += WandUtil.getPotencyLevel(caster);
        }
        ColorUtil colorUtil = new ColorUtil(0xb1abf1);
        if (staff.is(ModItems.NAMELESS_STAFF.get())) {
            colorUtil = new ColorUtil(0xa7fc3e);
        }
        damage += spellStat.getPotency();
        Vec3 vec3 = caster.getEyePosition();
        BlockHitResult rayTraceResult = this.blockResult(worldIn, caster, range);
        Entity target = MobUtil.getNearbyTarget(worldIn, caster, range, 1.0F);
        Optional<BlockPos> lightningRod = BlockFinder.findLightningRod(worldIn, BlockPos.containing(rayTraceResult.getLocation()), range);
        if (lightningRod.isPresent() && !rightStaff(staff)){
            BlockPos blockPos = lightningRod.get();
            ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
            this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
        } else {
            LivingEntity livingEntity = MobUtil.getLivingTarget(target);
            if (livingEntity != null && ForgeHooks.onLivingAttack(livingEntity, ModDamageSource.directShock(caster), damage)) {
                Vec3 vec31 = new Vec3(livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() / 2, livingEntity.getZ());
                ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, colorUtil, 10));
                if (livingEntity.hurt(ModDamageSource.directShock(caster), damage)){
                    float chance = rightStaff(staff) ? 0.25F : 0.05F;
                    float chainDamage = damage / 2.0F;
                    if (worldIn.isThundering() && worldIn.isRainingAt(livingEntity.blockPosition())){
                        chance += 0.25F;
                        chainDamage = damage;
                    }
                    if (worldIn.random.nextFloat() <= chance){
                        livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                    }
                    if (rightStaff(staff)){
                        WandUtil.chainLightning(livingEntity, caster, range / 4.0D, chainDamage);
                    }
                }
                this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
            } else {
                BlockPos blockPos = rayTraceResult.getBlockPos();
                ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
                this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
            }
        }
    }

