				if (caster != null) {
					Portal_Abyss_Blast_Entity DeathBeam1 = new Portal_Abyss_Blast_Entity(ModEntities.PORTAL_ABYSS_BLAST.get(), this.level(), this.getCaster(), this.getX(), this.getY(), this.getZ(), 0, (float) (90 * Math.PI / 180), laserdurations, 90,this.getDamage(),this.getHpDamage());
					this.level().addFreshEntity(DeathBeam1);
				}else{
					Portal_Abyss_Blast_Entity DeathBeam2 = new Portal_Abyss_Blast_Entity(ModEntities.PORTAL_ABYSS_BLAST.get(), this.level(), this.getX(), this.getY(), this.getZ(), 0, (float) (90 * Math.PI / 180), laserdurations,90,this.getDamage(),this.getHpDamage());
					this.level().addFreshEntity(DeathBeam2);
				}
			}


			if (!this.sentSpikeEvent) {
				this.level().broadcastEntityEvent(this, (byte)4);
				this.clientSideAttackStarted = true;
				this.sentSpikeEvent = true;
			}

			if (--this.lifeTicks < 0) {
				this.discard();
			}
		}
	}

@Nullable
	public LivingEntity getCaster() {
		if (this.caster == null && this.casterUuid != null && this.level() instanceof ServerLevel) {
			Entity entity = ((ServerLevel)this.level()).getEntity(this.casterUuid);
			if (entity instanceof LivingEntity) {
				this.caster = (LivingEntity)entity;
			}
		}

		return this.caster;
	}

@OnlyIn(Dist.CLIENT)
	public void handleEntityEvent(byte id) {
		super.handleEntityEvent(id);
		if (id == 4) {
			this.clientSideAttackStarted = true;
		}

	}

protected void readAdditionalSaveData(CompoundTag compound) {
		this.warmupDelayTicks = compound.getInt("Warmup");
		if (compound.hasUUID("Owner")) {
			this.casterUuid = compound.getUUID("Owner");
		}
		this.setDamage(compound.getFloat("damage"));
		this.setHpDamage(compound.getFloat("Hpdamage"));
	}

protected void addAdditionalSaveData(CompoundTag compound) {
		compound.putInt("Warmup", this.warmupDelayTicks);
		if (this.casterUuid != null) {
			compound.putUUID("Owner", this.casterUuid);
		}
		compound.putFloat("damage", this.getDamage());
		compound.putFloat("Hpdamage", this.getHpDamage());
	}

private void EarthQuake(UseOnContext context, Player player) {
        Level world = context.getLevel();

        boolean berserk = player.getHealth() <= player.getMaxHealth() * 0.5F;
        double radius = 4.0D;

        world.playSound(player, player.blockPosition(), ModSounds.EXPLOSION.get(), SoundSource.PLAYERS, 1.5F, 1.0F / (world.getRandom().nextFloat() * 0.4F + 0.8F));

        if (world.isClientSide) {
            BlockState block = world.getBlockState(context.getClickedPos());
            int numParticles = 80;
            for (int i = 0; i < numParticles; i++) {

                double angle = (double) i / numParticles * (Math.PI * 2.0D);
                double d0 = player.getX() + radius * Math.sin(angle);
                double d1 = player.getY() + 0.15D;
                double d2 = player.getZ() + radius * Math.cos(angle);

                double d3 = world.getRandom().nextGaussian() * 0.1D;
                double d4 = world.getRandom().nextGaussian() * 0.1D;
                double d5 = world.getRandom().nextGaussian() * 0.1D;

                world.addParticle(new BlockParticleOption(ParticleTypes.BLOCK, block), d0, d1, d2, d3, d4, d5);
                if (berserk) {
                    world.addParticle(ParticleTypes.FLAME, d0, d1, d2, d3, d4, d5);
                }
            }
        } else if (world instanceof ServerLevel serverLevel) {
            ScreenShake_Entity.ScreenShake(serverLevel, player.position(), 30, 0.1f, 0, 30);

            DamageSource shredderDamage = serverLevel.damageSources().playerAttack(player);
            float basedmg = AttributeUtils.OriginDamage(player, context.getItemInHand());

            List<Entity> list = serverLevel.getEntities(player, player.getBoundingBox().inflate(radius));
            for (Entity entity : list) {
                if (entity instanceof LivingEntity living) {
                    float bonusDamage = EnchantmentHelper.getDamageBonus(context.getItemInHand(), living.getMobType());
                    float enchanteddmg = basedmg + bonusDamage;

                    if (living.hurt(shredderDamage, enchanteddmg)) {
                        living.setDeltaMovement(living.getDeltaMovement().multiply(0.5D, 1.0D, 0.5D).add(0.0D, 0.6D, 0.0D));
                        if (berserk) {
                            living.setSecondsOnFire(5);
                        }
                    }

                }
            }
        }
    }

@Override
    public InteractionResult useOn(UseOnContext context) {
        ItemStack stack = context.getItemInHand();
        Player player = context.getPlayer();
        if(player !=null){
            if (player.getMainHandItem() == stack) {
                EarthQuake(context,player);
                player.getCooldowns().addCooldown(this, CMCommonConfig.InfernalForge.cooldown);
                return InteractionResult.sidedSuccess(context.getLevel().isClientSide);
            }
        }
        return super.useOn(context);
    }

public static float OriginDamage(LivingEntity living, ItemStack itemStack) {
		double totalDamage = living.getAttributeValue(Attributes.ATTACK_DAMAGE);

		if (living.getMainHandItem() == itemStack) {
			return (float) totalDamage;
		}

		ItemStack mainHandStack = living.getMainHandItem();
		if (!mainHandStack.isEmpty()) {
			Multimap<Attribute, AttributeModifier> modifiers = mainHandStack.getAttributeModifiers(EquipmentSlot.MAINHAND);

			if (modifiers.containsKey(Attributes.ATTACK_DAMAGE)) {
				for (AttributeModifier modifier : modifiers.get(Attributes.ATTACK_DAMAGE)) {
					if (modifier.getOperation() == AttributeModifier.Operation.ADDITION) {
						totalDamage -= modifier.getAmount();
					}
				}
			}
		}

		Multimap<Attribute, AttributeModifier> shredderModifiers = itemStack.getAttributeModifiers(EquipmentSlot.MAINHAND);
		if (shredderModifiers.containsKey(Attributes.ATTACK_DAMAGE)) {
			for (AttributeModifier modifier : shredderModifiers.get(Attributes.ATTACK_DAMAGE)) {
				if (modifier.getOperation() == AttributeModifier.Operation.ADDITION) {
					totalDamage += modifier.getAmount();
				}
			}
		}

		return (float) totalDamage;
	}
